const API = 'http://127.0.0.1:8416';
const key = $env.IMMICH_API_KEY;
if (!key) throw new Error('IMMICH_API_KEY is not configured');

const request = async (method, path, body) =>
  await this.helpers.httpRequest({
    method,
    url: `${API}${path}`,
    headers: {'x-api-key': key},
    body,
    json: true,
    timeout: 120000,
  });

// `force:false` only queues assets whose metadata job has not completed. A
// repeated run therefore repairs missing work without reprocessing the whole
// library.
await request('PUT', '/api/jobs/metadataExtraction', {command: 'start', force: false});
const duplicates = await request('GET', '/api/duplicates');

const esc = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
const size = (bytes) => {
  const value = Number(bytes ?? 0);
  if (!value) return 'unknown size';
  if (value >= 1024 ** 3) return `${(value / 1024 ** 3).toFixed(1)} GiB`;
  return `${(value / 1024 ** 2).toFixed(1)} MiB`;
};

const rows = duplicates
  .slice(0, 50)
  .map((group) => {
    const files = group.assets
      .map((asset) => {
        const keep = group.suggestedKeepAssetIds.includes(asset.id) ? 'keep' : 'review';
        return `<a href="https://immich.hugo-berendi.de/photos/${asset.id}" style="color:#9ccfd8;">${esc(asset.originalFileName)}</a> <span style="color:#6e6a86;">${size(asset.exifInfo?.fileSizeInByte)} · ${keep}</span>`;
      })
      .join('<br>');
    return `<tr><td style="padding:10px 0;border-bottom:1px solid #393552;color:#e0def4;">${files}</td></tr>`;
  })
  .join('');

const hidden = Math.max(0, duplicates.length - 50);
const html = `<html><body style="margin:0;padding:24px;background:#232136;color:#e0def4;font-family:Verdana,sans-serif;">
<table role="presentation" width="100%" style="max-width:600px;margin:auto;background:#2a273f;border:1px solid #393552;border-collapse:separate;padding:24px;">
<tr><td><div style="color:#c4a7e7;font:700 20px 'Courier New',monospace;">IMMICH MAINTENANCE</div>
<p style="color:#908caa;line-height:1.5;">Queued missing metadata extraction. Immich currently reports ${duplicates.length} duplicate group${duplicates.length === 1 ? '' : 's'}.</p></td></tr>
${rows || '<tr><td style="padding:12px 0;color:#9ccfd8;">No duplicate groups need review.</td></tr>'}
${hidden ? `<tr><td style="padding-top:12px;color:#f6c177;">${hidden} more groups are available in Immich.</td></tr>` : ''}
</table></body></html>`;

return [{json: {subject: `[Immich] Metadata repair queued · ${duplicates.length} duplicate groups`, html}}];
